{"command": "mkdir -p /tmp/w && cat > emd_sp.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <math.h>
/* sparse shortest augmenting path assignment. CSR: ptr[n+1], idx, cst.
   returns 0 ok, -1 infeasible. outputs row2col, v */
static int solve_sp(int n, const int *ptr, const int *idx, const double *cst,
                    int *row2col, double *v) {
    int *col2row = malloc(n*sizeof(int));
    double *d = malloc(n*sizeof(double));
    int *pred = malloc(n*sizeof(int));
    int *state = malloc(n*sizeof(int)); /* 0 unseen,1 in heap,2 final */
    int *fin = malloc(n*sizeof(int));
    int *touched = malloc(n*sizeof(int));
    int hcap = ptr[n] + n + 16;
    double *hk = malloc(hcap*sizeof(double));
    int *hv = malloc(hcap*sizeof(int));
    int ret = 0;
    for (int j=0;j<n;j++){col2row[j]=-1;v[j]=0;state[j]=0;}
    for (int i=0;i<n;i++) row2col[i]=-1;
    for (int s=0;s<n;s++){
        int hs=0, nf=0, nt=0;
        /* init from s */
        for (int e=ptr[s];e<ptr[s+1];e++){
            int j=idx[e]; double nd=cst[e]-v[j];
            if(state[j]==0){state[j]=1;touched[nt++]=j;d[j]=nd;pred[j]=s;}
            else if(nd<d[j]){d[j]=nd;pred[j]=s;} else continue;
            /* push */
            int k=hs++; while(k>0){int p=(k-1)>>1; if(hk[p]<=nd)break; hk[k]=hk[p];hv[k]=hv[p];k=p;} hk[k]=nd;hv[k]=j;
        }
        int sink=-1; double D=0;
        while(hs>0){
            double key=hk[0]; int j=hv[0];
            /* pop */
            hs--; if(hs>0){double lk=hk[hs]; int lv=hv[hs]; int k=0; for(;;){int c=2*k+1; if(c>=hs)break; if(c+1<hs&&hk[c+1]<hk[c])c++; if(hk[c]>=lk)break; hk[k]=hk[c];hv[k]=hv[c];k=c;} hk[k]=lk;hv[k]=lv;}
            if(state[j]==2 || key>d[j]) continue;
            state[j]=2; fin[nf++]=j;
            int i=col2row[j];
            if(i<0){sink=j;D=key;break;}
            int jc=row2col[i];
            double ui=0; /* u_i = c_i,jc - v_jc */
            for(int e=ptr[i];e<ptr[i+1];e++) if(idx[e]==jc){ui=cst[e]-v[jc];break;}
            for(int e=ptr[i];e<ptr[i+1];e++){
                int k2=idx[e]; if(state[k2]==2) continue;
                double nd=key+cst[e]-v[k2]-ui;
                if(state[k2]==0){state[k2]=1;touched[nt++]=k2;}
                else if(nd>=d[k2]) continue;
                d[k2]=nd;pred[k2]=i;
                if(hs>=hcap){hcap*=2;hk=realloc(hk,hcap*sizeof(double));hv=realloc(hv,hcap*sizeof(int));}
                int k=hs++; while(k>0){int p=(k-1)>>1; if(hk[p]<=nd)break; hk[k]=hk[p];hv[k]=hv[p];k=p;} hk[k]=nd;hv[k]=k2;
            }
        }
        if(sink<0){ret=-1;break;}
        for(int t=0;t<nf;t++){int j=fin[t]; v[j]+=d[j]-D;}
        for(int t=0;t<nt;t++) state[touched[t]]=0;
        /* augment */
        int j=sink;
        for(;;){int i=pred[j]; col2row[j]=i; int pj=row2col[i]; row2col[i]=j; if(i==s)break; j=pj;}
    }
    free(col2row);free(d);free(pred);free(state);free(fin);free(touched);free(hk);free(hv);
    return ret;
}

/* M dense n x n row-major. k neighbors per row (and per col). returns number of iterations, -1 on failure */
int emd_assign(int n, const double *M, int k, int *row2col) {
    if(k>n)k=n;
    char *mask = calloc((size_t)n*n,1);
    double *bk = malloc(k*sizeof(double)); int *bi = malloc(k*sizeof(int));
    /* rows */
    for(int i=0;i<n;i++){
        const double *r=M+(size_t)i*n; int c=0;
        for(int j=0;j<n;j++){double x=r[j];
            if(c<k){int p=c++; while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bi[p]=bi[p-1];p--;} bk[p]=x;bi[p]=j;}
            else if(x<bk[k-1]){int p=k-1; while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bi[p]=bi[p-1];p--;} bk[p]=x;bi[p]=j;}
        }
        for(int t=0;t<k;t++) mask[(size_t)i*n+bi[t]]=1;
    }
    /* cols */
    for(int j=0;j<n;j++){
        int c=0;
        for(int i=0;i<n;i++){double x=M[(size_t)i*n+j];
            if(c<k){int p=c++; while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bi[p]=bi[p-1];p--;} bk[p]=x;bi[p]=i;}
            else if(x<bk[k-1]){int p=k-1; while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bi[p]=bi[p-1];p--;} bk[p]=x;bi[p]=i;}
        }
        for(int t=0;t<k;t++) mask[(size_t)bi[t]*n+j]=1;
    }
    free(bk);free(bi);
    int *ptr=malloc((n+1)*sizeof(int));
    double *v=malloc(n*sizeof(double));
    int iter=0, result=-1;
    for(;iter<50;iter++){
        int E=0; for(size_t q=0;q<(size_t)n*n;q++) E+=mask[q];
        int *idx=malloc(E*sizeof(int)); double *cst=malloc(E*sizeof(double));
        int e=0; ptr[0]=0;
        for(int i=0;i<n;i++){ for(int j=0;j<n;j++) if(mask[(size_t)i*n+j]){idx[e]=j;cst[e]=M[(size_t)i*n+j];e++;} ptr[i+1]=e;}
        int r=solve_sp(n,ptr,idx,cst,row2col,v);
        free(idx);free(cst);
        if(r<0){ /* infeasible: go dense */ memset(mask,1,(size_t)n*n); continue; }
        /* check duals */
        int viol=0;
        for(int i=0;i<n;i++){
            const double *row=M+(size_t)i*n; double ui=row[row2col[i]]-v[row2col[i]];
            for(int j=0;j<n;j++){ if(row[j]-v[j]-ui < -1e-12 && !mask[(size_t)i*n+j]){mask[(size_t)i*n+j]=1;viol++;} }
        }
        if(!viol){result=iter;break;}
    }
    free(mask);free(ptr);free(v);
    return result;
}
