{"command": "cat > emd_sp.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct { int *ptr, *cnt, *idx; double *cst; int cap; } G_t; /* fixed-capacity rows */

static void ins(double *bk, int *bi, int *c, int k, double x, int j){
    int p;
    if(*c<k){p=(*c)++;} else { if(x>=bk[k-1]) return; p=k-1; }
    while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bi[p]=bi[p-1];p--;} bk[p]=x;bi[p]=j;
}

static int ssp(int n, G_t *g, int *row2col, int *col2row, double *v, double *u,
               const int *frees, int nfree, double *d, int *pred, int *state, int *fin, int *touched,
               double **hkp, int **hvp, int *hcapp){
    double *hk=*hkp; int *hv=*hvp; int hcap=*hcapp; int ret=0;
    for (int q=0;q<nfree;q++){ int s=frees[q];
        int hs=0, nf=0, nt=0;
        const int *ix=g->idx+g->ptr[s]; const double *cs=g->cst+g->ptr[s]; int m=g->cnt[s];
        for (int e=0;e<m;e++){
            int j=ix[e]; double nd=cs[e]-v[j];
            if(state[j]==0){state[j]=1;touched[nt++]=j;}
            else if(nd>=d[j]) continue;
            d[j]=nd;pred[j]=s;
            if(hs>=hcap){hcap*=2;hk=realloc(hk,hcap*sizeof(double));hv=realloc(hv,hcap*sizeof(int));}
            int k=hs++; while(k>0){int p=(k-1)>>1; if(hk[p]<=nd)break; hk[k]=hk[p];hv[k]=hv[p];k=p;} hk[k]=nd;hv[k]=j;
        }
        int sink=-1; double D=0;
        while(hs>0){
            double key=hk[0]; int j=hv[0];
            hs--; if(hs>0){double lk=hk[hs]; int lv=hv[hs]; int k=0; for(;;){int c=2*k+1; if(c>=hs)break; if(c+1<hs&&hk[c+1]<hk[c])c++; if(hk[c]>=lk)break; hk[k]=hk[c];hv[k]=hv[c];k=c;} hk[k]=lk;hv[k]=lv;}
            if(state[j]==2 || key>d[j]) continue;
            state[j]=2; fin[nf++]=j;
            int i=col2row[j];
            if(i<0){sink=j;D=key;break;}
            double ui=u[i];
            const int *ix2=g->idx+g->ptr[i]; const double *cs2=g->cst+g->ptr[i]; int m2=g->cnt[i];
            for(int e=0;e<m2;e++){
                int k2=ix2[e]; if(state[k2]==2) continue;
                double nd=key+cs2[e]-v[k2]-ui;
                if(state[k2]==0){state[k2]=1;touched[nt++]=k2;}
                else if(nd>=d[k2]) continue;
                d[k2]=nd;pred[k2]=i;
                if(hs>=hcap){hcap*=2;hk=realloc(hk,hcap*sizeof(double));hv=realloc(hv,hcap*sizeof(int));}
                int k=hs++; while(k>0){int p=(k-1)>>1; if(hk[p]<=nd)break; hk[k]=hk[p];hv[k]=hv[p];k=p;} hk[k]=nd;hv[k]=k2;
            }
        }
        if(sink<0){ret=-1;break;}
        for(int t=0;t<nf;t++){int j=fin[t]; v[j]+=d[j]-D;}
        for(int t=0;t<nt;t++) state[touched[t]]=0;
        int j=sink;
        for(;;){int i=pred[j]; col2row[j]=i; int pj=row2col[i]; row2col[i]=j;
            /* update u_i so that edge (i,j) tight */
            const int *ix3=g->idx+g->ptr[i]; const double *cs3=g->cst+g->ptr[i]; int m3=g->cnt[i];
            for(int e=0;e<m3;e++) if(ix3[e]==j){u[i]=cs3[e]-v[j];break;}
            if(i==s)break; j=pj;}
    }
    *hkp=hk;*hvp=hv;*hcapp=hcap;
    return ret;
}

int emd_assign(int n, const double *M, int k, int *row2col) {
    if(k>n)k=n;
    int cap=n; /* each row capacity n (simple) */
    G_t g; g.ptr=malloc(n*sizeof(int)); g.cnt=calloc(n,sizeof(int));
    g.idx=malloc((size_t)n*cap*sizeof(int)); g.cst=malloc((size_t)n*cap*sizeof(double));
    for(int i=0;i<n;i++) g.ptr[i]=i*cap;
    char *mask = calloc((size_t)n*n,1);
    double *bk = malloc(k*sizeof(double)); int *bi = malloc(k*sizeof(int));
    double *cbk = malloc((size_t)n*k*sizeof(double)); int *cbi = malloc((size_t)n*k*sizeof(int));
    int *cc = calloc(n,sizeof(int));
    for(int i=0;i<n;i++){
        const double *r=M+(size_t)i*n; int c=0;
        for(int j=0;j<n;j++){double x=r[j];
            ins(bk,bi,&c,k,x,j);
            if(cc[j]<k || x<cbk[(size_t)j*k+k-1]) ins(cbk+(size_t)j*k,cbi+(size_t)j*k,cc+j,k,x,i);
        }
        for(int t=0;t<k;t++) mask[(size_t)i*n+bi[t]]=1;
    }
    for(int j=0;j<n;j++) for(int t=0;t<k;t++) mask[(size_t)cbi[(size_t)j*k+t]*n+j]=1;
    for(int i=0;i<n;i++) mask[(size_t)i*n+i]=1;
    for(int i=0;i<n;i++){ const char *mr=mask+(size_t)i*n; const double *r=M+(size_t)i*n; int b=g.ptr[i], c=0;
        for(int j=0;j<n;j++) if(mr[j]){g.idx[b+c]=j;g.cst[b+c]=r[j];c++;} g.cnt[i]=c; }
