                          ctypes.c_double, ctypes.c_double, ctypes.c_double]


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        # Uniform equal-size marginals: EMD reduces to a linear assignment problem
        # (an optimal vertex of the transport polytope is a scaled permutation matrix).
        if (n > 1 and M.ndim == 2 and M.shape == (n, n) and b.shape[0] == n
                and np.all(a == a[0]) and np.all(b == a[0]) and np.all(np.isfinite(M))):
